class Solution {
    public int findMin(int[] nums) {
        int lo = 0;
        int hi = nums.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] > nums[hi]) {
                lo = mid + 1;
            } else if (nums[mid] < nums[hi]) {
                hi = mid;
            } else {
                hi--;
            }
        }
        return nums[lo];
    }
}

class Solution {
    public int findMin(int[] nums) {
        int lo = 0;
        int hi = nums.length - 1;
        while (lo < hi) {
            while (lo < hi && nums[lo] == nums[hi]) {
                hi--;
            }
            if (nums[lo] <= nums[hi]) {
                return nums[lo];
            }
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] >= nums[lo]) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return nums[lo];
    }
}

class Solution {
    public int findMin(int[] nums) {
        int minimum = nums[0];
        for (int value : nums) {
            if (value < minimum) {
                minimum = value;
            }
        }
        return minimum;
    }
}

class Solution {
    public int findMin(int[] nums) {
        return search(nums, 0, nums.length - 1);
    }

    private int search(int[] nums, int lo, int hi) {
        if (lo == hi) return nums[lo];
        if (nums[lo] < nums[hi]) return nums[lo];
        int mid = lo + (hi - lo) / 2;
        int left = search(nums, lo, mid);
        int right = search(nums, mid + 1, hi);
        return Math.min(left, right);
    }
}
